```rust
use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn main() {
    let s = Semaphore::new(1);

    let s1 = Arc::clone(&s);
    let w1 = thread::spawn(move || {
        let _permit = s1.acquire();
        drop(_permit);
    });

    let s2 = Arc::clone(&s);
    let w2 = thread::spawn(move || {
        let _permit = s2.acquire();
        drop(_permit);
    });

    w1.join().unwrap();
    w2.join().unwrap();

    println!("DONE permits=1");
}
```
